function normalizarTelefonoAR(raw) {
  let t = (raw || '').toString().replace(/[^0-9+]/g, '');
  if (!t.startsWith('+')) { t = t.startsWith('54') ? '+' + t : '+54' + t; }
  if (t.startsWith('+54') && !t.startsWith('+549')) t = '+549' + t.slice(3);
  return t;
}
function normalizarEmail(raw) {
  return (raw || '').toString().trim().toLowerCase();
}
function pick(obj, keys) {
  for (const k of keys) { if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k]; }
  return '';
}

// 'Leer Leads Institucional' llega como input principal de este nodo; 'Leer Leads Meta' se referencia aparte.
const institucional = $input.all().map(item => ({ raw: item.json, fuente: 'institucional' }));
const meta = $('Leer Leads Meta').all().map(item => ({ raw: item.json, fuente: 'meta' }));

const porTelefono = new Map();
for (const { raw, fuente } of [...institucional, ...meta]) {
  const telefono = normalizarTelefonoAR(pick(raw, ['telefono', 'Telefono', 'phone', 'Phone']));
  if (!telefono || telefono.replace(/\D/g, '').length < 8) continue; // descarta filas sin telefono valido

  const email = normalizarEmail(pick(raw, ['email', 'Email', 'mail', 'Mail']));
  const nombre = pick(raw, ['nombre', 'Nombre', 'name', 'Name']).toString().trim();

  const existente = porTelefono.get(telefono);
  if (!existente) {
    porTelefono.set(telefono, { telefono, nombre, email, fuente });
  } else if (fuente === 'institucional') {
    // Prioridad: Institucional pisa datos de Meta si el telefono se repite en ambas fuentes.
    existente.nombre = nombre || existente.nombre;
    existente.email = email || existente.email;
    existente.fuente = 'institucional';
  } else {
    existente.nombre = existente.nombre || nombre;
    existente.email = existente.email || email;
  }
}

return Array.from(porTelefono.values()).map(j => ({ json: j }));
